// src/utils/api.js
import axios from "axios";

const api = axios.create({
  baseURL: "/backend",
  withCredentials: true,
  timeout: 20000,
});

// Attache le Bearer si présent
api.interceptors.request.use((config) => {
  const t = localStorage.getItem("adminToken") || sessionStorage.getItem("adminToken");
  if (t && !config.headers?.Authorization) {
    config.headers = { ...(config.headers || {}), Authorization: `Bearer ${t}` };
  }
  return config;
});

let isRefreshing = false;
let pending = [];

// Util: applique le nouveau token aux requêtes en attente
function applyNewToken(token) {
  pending.forEach((resume) => resume(token));
  pending = [];
}

api.interceptors.response.use(
  (r) => r,
  async (err) => {
    const status = err?.response?.status;
    const code   = err?.response?.data?.error || err?.response?.data?.name;
    const original = err?.config;

    // Log utile
    console.error("API error:", status, original?.method?.toUpperCase(), original?.url, err?.response?.data);

    // Essai de refresh si 401 dû à l'expiration et qu'on n'a pas déjà tenté sur cette requête
    const isTokenExpired = status === 401 && /tokenexpired/i.test(String(code)); // "TokenExpiredError"
    if (isTokenExpired && !original.__retry) {
      original.__retry = true;

      // Orchestration du refresh (éviter appels parallèles)
      if (!isRefreshing) {
        isRefreshing = true;
        try {
          const { data } = await axios.post("/backend/admin/refresh", {}, { withCredentials: true });
          const newToken = data?.token;
          if (newToken) {
            // stocke le nouveau token
            localStorage.setItem("adminToken", newToken);
            // met à jour l'instance axios
            api.defaults.headers.common.Authorization = `Bearer ${newToken}`;
            applyNewToken(newToken);
          } else {
            throw new Error("No token in /admin/refresh response");
          }
        } catch (e) {
          // échec refresh → nettoyage + redirection
          localStorage.removeItem("adminToken");
          sessionStorage.removeItem("adminToken");
          const here = window.location.pathname + window.location.search;
          if (!here.startsWith("/admin/login")) {
            window.location.assign(`/admin/login?next=${encodeURIComponent(here)}`);
          }
          isRefreshing = false;
          applyNewToken(null);
          return Promise.reject(err);
        }
        isRefreshing = false;
      }

      // Met la requête en attente du refresh
      return new Promise((resolve, reject) => {
        pending.push((token) => {
          if (!token) return reject(err);
          // rejoue la requête initiale avec le nouveau token
          original.headers = { ...(original.headers || {}), Authorization: `Bearer ${token}` };
          resolve(api(original));
        });
      });
    }

    // Autres 401/403 → nettoyage + redirection
    if (status === 401 || status === 403) {
      localStorage.removeItem("adminToken");
      sessionStorage.removeItem("adminToken");
      const here = window.location.pathname + window.location.search;
      if (!here.startsWith("/admin/login")) {
        window.location.assign(`/admin/login?next=${encodeURIComponent(here)}`);
      }
    }

    return Promise.reject(err);
  }
);

export default api;
